#include <zephyr/json/json.h>
#include <zephyr/logging/log.h>
#include <zephyr/sys/util.h>

#include <ctype.h>
#include <errno.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>

LOG_MODULE_REGISTER(json, CONFIG_JSON_LOG_LEVEL);

#define JSON_TOKEN_BUF_LEN 16

static char json_token_buf[JSON_TOKEN_BUF_LEN];

static int json_skip_whitespace(const char *json, size_t len, size_t *offset)
{
	while (*offset < len) {
		if (!isspace((unsigned char)json[*offset])) {
			break;
		}
		(*offset)++;
	}

	return 0;
}

static int json_skip_string(const char *json, size_t len, size_t *offset)
{
	(*offset)++; /* Skip opening quote */

	while (*offset < len) {
		if (json[*offset] == '"') {
			(*offset)++;
			return 0;
		}

		if (json[*offset] == '\\') {
			(*offset)++; /* Skip backslash */
			if (*offset == len) {
				return -EINVAL;
			}
		}
		(*offset)++;
	}

	return -EINVAL;
}

static int json_skip_value(const char *json, size_t len, size_t *offset)
{
	int err;

	err = json_skip_whitespace(json, len, offset);
	if (err) {
		return err;
	}

	if (*offset == len) {
		return -EINVAL;
	}

	switch (json[*offset]) {
	case '{':
		(*offset)++;
		err = json_skip_whitespace(json, len, offset);
		if (err) {
			return err;
		}

		if (*offset == len) {
			return -EINVAL;
		}

		if (json[*offset] == '}') {
			(*offset)++;
			return 0;
		}

		while (*offset < len) {
			err = json_skip_string(json, len, offset);
			if (err) {
				return err;
			}

			err = json_skip_whitespace(json, len, offset);
			if (err) {
				return err;
			}

			if (*offset == len || json[*offset] != ':') {
				return -EINVAL;
			}
			(*offset)++;

			err = json_skip_value(json, len, offset);
			if (err) {
				return err;
			}

			err = json_skip_whitespace(json, len, offset);
			if (err) {
				return err;
			}

			if (*offset == len) {
				return -EINVAL;
			}

			if (json[*offset] == '}') {
				(*offset)++;
				return 0;
			}

			if (json[*offset] != ',') {
				return -EINVAL;
			}
			(*offset)++;
		}
		break;

	case '[':
		(*offset)++;
		err = json_skip_whitespace(json, len, offset);
		if (err) {
			return err;
		}

		if (*offset == len) {
			return -EINVAL;
		}

		if (json[*offset] == ']') {
			(*offset)++;
			return 0;
		}

		while (*offset < len) {
			err = json_skip_value(json, len, offset);
			if (err) {
				return err;
			}

			err = json_skip_whitespace(json, len, offset);
			if (err) {
				return err;
			}

			if (*offset == len) {
				return -EINVAL;
			}

			if (json[*offset] == ']') {
				(*offset)++;
				return 0;
			}

			if (json[*offset] != ',') {
				return -EINVAL;
			}
			(*offset)++;
		}
		break;

	case '"':
		return json_skip_string(json, len, offset);

	case 't': /* true */
		if (len - *offset < 4 || memcmp(&json[*offset], "true", 4) != 0) {
			return -EINVAL;
		}
		*offset += 4;
		return 0;

	case 'f': /* false */
		if (len - *offset < 5 || memcmp(&json[*offset], "false", 5) != 0) {
			return -EINVAL;
		}
		*offset += 5;
		return 0;

	case 'n': /* null */
		if (len - *offset < 4 || memcmp(&json[*offset], "null", 4) != 0) {
			return -EINVAL;
		}
		*offset += 4;
		return 0;

	default:
		if (json[*offset] == '-' || isdigit((unsigned char)json[*offset])) {
			(*offset)++;
			while (*offset < len && isdigit((unsigned char)json[*offset])) {
				(*offset)++;
			}

			if (*offset < len && json[*offset] == '.') {
				(*offset)++;
				while (*offset < len && isdigit((unsigned char)json[*offset])) {
					(*offset)++;
				}
			}

			if (*offset < len && (json[*offset] == 'e' || json[*offset] == 'E')) {
				(*offset)++;
				if (*offset < len && (json[*offset] == '+' || json[*offset] == '-')) {
					(*offset)++;
				}
				while (*offset < len && isdigit((unsigned char)json[*offset])) {
					(*offset)++;
				}
			}
			return 0;
		}
		break;
	}

	return -EINVAL;
}

static int json_token_get(const char *json, size_t len, size_t *offset,
			  enum json_token_type *type, const char **token, size_t *token_len)
{
	int err;

	err = json_skip_whitespace(json, len, offset);
	if (err) {
		return err;
	}

	if (*offset == len) {
		return -ENODATA;
	}

	*token = &json[*offset];

	switch (json[*offset]) {
	case '{':
		*type = JSON_TOKEN_TYPE_START_OBJECT;
		*token_len = 1;
		break;

	case '}':
		*type = JSON_TOKEN_TYPE_END_OBJECT;
		*token_len = 1;
		break;

	case '[':
		*type = JSON_TOKEN_TYPE_START_ARRAY;
		*token_len = 1;
		break;

	case ']':
		*type = JSON_TOKEN_TYPE_END_ARRAY;
		*token_len = 1;
		break;

	case ':':
		*type = JSON_TOKEN_TYPE_COLON;
		*token_len = 1;
		break;

	case ',':
		*type = JSON_TOKEN_TYPE_COMMA;
		*token_len = 1;
		break;

	case '"':
		*type = JSON_TOKEN_TYPE_STRING;
		(*offset)++; /* Skip opening quote */
		*token = &json[*offset];

		while (*offset < len) {
			if (json[*offset] == '"') {
				*token_len = &json[*offset] - *token;
				break;
			}

			if (json[*offset] == '\\') {
				(*offset)++; /* Skip backslash */
				if (*offset == len) {
					return -EINVAL;
				}
			}
			(*offset)++;
		}

		if (json[*offset] != '"') {
			return -EINVAL;
		}
		break;

	case 't': /* true */
		*type = JSON_TOKEN_TYPE_TRUE;
		*token_len = 4;
		if (len - *offset < *token_len || memcmp(&json[*offset], "true", *token_len) != 0) {
			return -EINVAL;
		}
		break;

	case 'f': /* false */
		*type = JSON_TOKEN_TYPE_FALSE;
		*token_len = 5;
		if (len - *offset < *token_len || memcmp(&json[*offset], "false", *token_len) != 0) {
			return -EINVAL;
		}
		break;

	case 'n': /* null */
		*type = JSON_TOKEN_TYPE_NULL;
		*token_len = 4;
		if (len - *offset < *token_len || memcmp(&json[*offset], "null", *token_len) != 0) {
			return -EINVAL;
		}
		break;

	default:
		if (json[*offset] == '-' || isdigit((unsigned char)json[*offset])) {
			*type = JSON_TOKEN_TYPE_NUMBER;
			(*offset)++;
			while (*offset < len && isdigit((unsigned char)json[*offset])) {
				(*offset)++;
			}

			if (*offset < len && json[*offset] == '.') {
				(*offset)++;
				while (*offset < len && isdigit((unsigned char)json[*offset])) {
					(*offset)++;
				}
			}

			if (*offset < len && (json[*offset] == 'e' || json[*offset] == 'E')) {
				(*offset)++;
				if (*offset < len && (json[*offset] == '+' || json[*offset] == '-')) {
					(*offset)++;
				}
				while (*offset < len && isdigit((unsigned char)json[*offset])) {
					(*offset)++;
				}
			}
			*token_len = &json[*offset] - *token;
			(*offset)--; /* Decrement to point to last char of token */
			break;
		}

		return -EINVAL;
	}

	(*offset)++;

	return 0;
}

static int json_token_value_get(const char *json, size_t len, size_t *offset,
				  enum json_token_type *type, const char **token, size_t *token_len)
{
	int err;

	err = json_token_get(json, len, offset, type, token, token_len);
	if (err) {
		return err;
	}

	if (*type == JSON_TOKEN_TYPE_START_OBJECT ||
	    *type == JSON_TOKEN_TYPE_END_OBJECT ||
	    *type == JSON_TOKEN_TYPE_START_ARRAY ||
	    *type == JSON_TOKEN_TYPE_END_ARRAY ||
	    *type == JSON_TOKEN_TYPE_COLON ||
	    *type == JSON_TOKEN_TYPE_COMMA) {
		return -EINVAL;
	}

	return 0;
}

static int json_token_string_get(const char *json, size_t len, size_t *offset,
				   const char **token, size_t *token_len)
{
	enum json_token_type type;
	int err;

	err = json_token_get(json, len, offset, &type, token, token_len);
	if (err) {
		return err;
	}

	if (type != JSON_TOKEN_TYPE_STRING) {
		return -EINVAL;
	}

	return 0;
}

static int json_token_obj_start_get(const char *json, size_t len, size_t *offset)
{
	enum json_token_type type;
	const char *token;
	size_t token_len;
	int err;

	err = json_token_get(json, len, offset, &type, &token, &token_len);
	if (err) {
		return err;
	}

	if (type != JSON_TOKEN_TYPE_START_OBJECT) {
		return -EINVAL;
	}

	return 0;
}

static int json_token_obj_end_get(const char *json, size_t len, size_t *offset)
{
	enum json_token_type type;
	const char *token;
	size_t token_len;
	int err;

	err = json_token_get(json, len, offset, &type, &token, &token_len);
	if (err) {
		return err;
	}

	if (type != JSON_TOKEN_TYPE_END_OBJECT) {
