static int json_token_comma_get(const char *json, size_t len, size_t *offset)
{
	enum json_token_type type;
	const char *token;
	size_t token_len;
	int err;

	err = json_token_get(json, len, offset, &type, &token, &token_len);
	if (err) {
		return err;
	}

	if (type != JSON_TOKEN_TYPE_COMMA) {
		return -EINVAL;
	}

	return 0;
}

static int json_token_value_skip(const char *json, size_t len, size_t *offset)
{
	enum json_token_type type;
	const char *token;
	size_t token_len;
	int err;

	err = json_token_get(json, len, offset, &type, &token, &token_len);
	if (err) {
		return err;
	}

	switch (type) {
	case JSON_TOKEN_TYPE_START_OBJECT:
		err = json_skip_value(json, len, offset);
		if (err) {
			return err;
		}
		break;

	case JSON_TOKEN_TYPE_START_ARRAY:
		err = json_skip_value(json, len, offset);
		if (err) {
			return err;
		}
		break;

	case JSON_TOKEN_TYPE_END_OBJECT:
	case JSON_TOKEN_TYPE_END_ARRAY:
	case JSON_TOKEN_TYPE_COLON:
	case JSON_TOKEN_TYPE_COMMA:
		return -EINVAL;

	default:
		/* Value token, nothing to skip */
		break;
	}

	return 0;
}

static int json_unescape(char *dst, size_t dst_len, const char *src, size_t src_len)
{
	size_t i;
	size_t j;

	for (i = 0, j = 0; i < src_len && j < dst_len; i++, j++) {
		if (src[i] == '\\') {
			i++;
			if (i == src_len) {
				return -EINVAL;
			}

			switch (src[i]) {
			case '"':
			case '\\':
			case '/':
				dst[j] = src[i];
				break;

			case 'b':
				dst[j] = '\b';
				break;

			case 'f':
				dst[j] = '\f';
				break;

			case 'n':
				dst[j] = '\n';
				break;

			case 'r':
				dst[j] = '\r';
				break;

			case 't':
				dst[j] = '\t';
				break;

			case 'u':
				/* TODO: Handle unicode characters */
				return -ENOTSUP;

			default:
				return -EINVAL;
			}
		} else {
			dst[j] = src[i];
		}
	}

	if (i < src_len) {
		return -ENOMEM;
	}

	return j;
}

static int json_parse_string(const char *json, size_t len, size_t *offset,
			     char *str, size_t str_len)
{
	const char *token;
	size_t token_len;
	int err;

	err = json_token_string_get(json, len, offset, &token, &token_len);
	if (err) {
		return err;
	}

	if (str == NULL) {
		return 0;
	}

	err = json_unescape(str, str_len, token, token_len);
	if (err < 0) {
		return err;
	}

	if (err == str_len) {
		return -ENOMEM;
	}

	str[err] = '\0';

	return 0;
}

static int json_parse_bool(const char *json, size_t len, size_t *offset, bool *val)
{
	enum json_token_type type;
	const char *token;
	size_t token_len;
	int err;

	err = json_token_value_get(json, len, offset, &type, &token, &token_len);
	if (err) {
		return err;
	}

	if (val == NULL) {
		return 0;
	}

	if (type == JSON_TOKEN_TYPE_TRUE) {
		*val = true;
	} else if (type == JSON_TOKEN_TYPE_FALSE) {
		*val = false;
	} else {
		return -EINVAL;
	}

	return 0;
}

static int json_parse_int(const char *json, size_t len, size_t *offset, int32_t *val)
{
	enum json_token_type type;
	const char *token;
	size_t token_len;
	int err;

	err = json_token_value_get(json, len, offset, &type, &token, &token_len);
	if (err) {
		return err;
	}

	if (val == NULL) {
		return 0;
	}

	if (type != JSON_TOKEN_TYPE_NUMBER) {
		return -EINVAL;
	}

	if (token_len >= JSON_TOKEN_BUF_LEN) {
		return -ENOMEM;
	}

	memcpy(json_token_buf, token, token_len);
	json_token_buf[token_len] = '\0';

	*val = strtol(json_token_buf, NULL, 10);

	return 0;
}

