	*val = strtod(json_token_buf, NULL);

	return 0;
}

static int json_parse_token(const char *json, size_t len, size_t *offset,
			    struct json_token *token)
{
	enum json_token_type type;
	const char *token_ptr;
	size_t token_len;
	int err;

	err = json_token_value_get(json, len, offset, &type, &token_ptr, &token_len);
	if (err) {
		return err;
	}

	if (token == NULL) {
		return 0;
	}

	token->type = type;
	token->ptr = token_ptr;
	token->len = token_len;

	return 0;
}

static int json_parse_obj_content(const char *json, size_t len, size_t *offset,
				  const struct json_obj_descr *descr,
				  size_t descr_len, void *data)
{
	enum json_token_type type;
	const char *token;
	size_t token_len;
	int err;

	while (true) {
		err = json_token_get(json, len, offset, &type, &token, &token_len);
		if (err) {
			return err;
		}

		if (type == JSON_TOKEN_TYPE_END_OBJECT) {
			break;
		}

		if (type == JSON_TOKEN_TYPE_COMMA) {
			err = json_token_get(json, len, offset, &type, &token, &token_len);
			if (err) {
				return err;
			}
		}

		if (type != JSON_TOKEN_TYPE_STRING) {
			return -EINVAL;
		}

		const struct json_obj_descr *d = NULL;

		for (size_t i = 0; i < descr_len; i++) {
			if (token_len == strlen(descr[i].field_name) &&
			    memcmp(token, descr[i].field_name, token_len) == 0) {
				d = &descr[i];
				break;
			}
		}

		err = json_token_colon_get(json, len, offset);
		if (err) {
			return err;
		}

		if (d == NULL) {
			LOG_DBG("Unknown field: %.*s", (int)token_len, token);
			err = json_token_value_skip(json, len, offset);
			if (err) {
				return err;
			}
			continue;
		}

		void *field_data = (char *)data + d->field_offset;

		switch (d->field_type) {
		case JSON_OBJ_DESCR_FIELD_TYPE_BOOL:
			err = json_parse_bool(json, len, offset, field_data);
			break;

		case JSON_OBJ_DESCR_FIELD_TYPE_INT:
			err = json_parse_int(json, len, offset, field_data);
			break;

		case JSON_OBJ_DESCR_FIELD_TYPE_UINT:
			err = json_parse_uint(json, len, offset, field_data);
			break;

		case JSON_OBJ_DESCR_FIELD_TYPE_STRING:
			err = json_parse_string(json, len, offset, field_data, d->field_size);
			break;

		case JSON_OBJ_DESCR_FIELD_TYPE_STRING_ARRAY:
			err = json_arr_parse(field_data, json, len, offset, NULL, 0, d->field_size);
			break;

		case JSON_OBJ_DESCR_FIELD_TYPE_OBJECT:
			err = json_obj_parse(field_data, json, len, offset, d->object_descr,
					     d->object_descr_len);
			break;

		case JSON_OBJ_DESCR_FIELD_TYPE_OBJECT_ARRAY:
			err = json_arr_parse(field_data, json, len, offset, d->object_descr,
					     d->object_descr_len, d->field_size);
			break;

		case JSON_OBJ_DESCR_FIELD_TYPE_S64:
			err = json_parse_s64(json, len, offset, field_data);
			break;

		case JSON_OBJ_DESCR_FIELD_TYPE_U64:
			err = json_parse_u64(json, len, offset, field_data);
			break;

		case JSON_OBJ_DESCR_FIELD_TYPE_FLOAT:
			err = json_parse_float(json, len, offset, field_data);
			break;

		case JSON_OBJ_DESCR_FIELD_TYPE_TOKEN:
			err = json_parse_token(json, len, offset, field_data);
			break;

		default:
			return -EINVAL;
		}

		if (err) {
			return err;
		}
	}

	return 0;
}

int json_obj_parse(void *data, const char *json, size_t len, size_t *offset,
		   const struct json_obj_descr *descr, size_t descr_len)
{
	int err;

	err = json_token_obj_start_get(json, len, offset);
	if (err) {
		return err;
	}

	err = json_parse_obj_content(json, len, offset, descr, descr_len, data);
	if (err) {
		return err;
	}

	return 0;
}

static int json_arr_parse_nested(struct json_arr *arr, const char *json, size_t len,
				   size_t *offset, const struct json_obj_descr *descr,
				   size_t descr_len, size_t element_size)
{
	enum json_token_type type;
	const char *token;
	size_t token_len;
	int err;
	size_t count;

	err = json_token_arr_start_get(json, len, offset);
	if (err) {
		return err;
	}

	err = json_token_get(json, len, offset, &type, &token, &token_len);
	if (err) {
		return err;
	}

	if (type == JSON_TOKEN_TYPE_END_ARRAY) {
		arr->elements_count = 0;
		return 0;
	}

	for (count = 0; ; count++) {
		if (arr->elements && count == arr->max_elements) {
			return -EINVAL;
		}

		if (count > 0) {
			if (type != JSON_TOKEN_TYPE_COMMA) {
				return -EINVAL;
			}

			err = json_token_get(json, len, offset, &type, &token, &token_len);
			if (err) {
				return err;
			}
		}

		if (descr) {
			if (type != JSON_TOKEN_TYPE_START_OBJECT) {
				return -EINVAL;
			}

			void *element_data = (char *)arr->elements + (count * element_size);

			err = json_parse_obj_content(json, len, offset, descr, descr_len,
						     element_data);
			if (err) {
				return err;
			}
		} else {
			void *element_data = (char *)arr->elements + (count * element_size);

			switch (element_size) {
			case sizeof(bool):
				err = json_parse_bool(json, len, offset, element_data);
				break;

			case sizeof(int32_t):
				err = json_parse_int(json, len, offset, element_data);
				break;

			case sizeof(uint32_t):
				err = json_parse_uint(json, len, offset, element_data);
				break;

			case sizeof(int64_t):
				err = json_parse_s64(json, len, offset, element_data);
				break;

			case sizeof(uint64_t):
				err = json_parse_u64(json, len, offset, element_data);
				break;

			case sizeof(double):
				err = json_parse_float(json, len, offset, element_data);
				break;

			case sizeof(struct json_token):
				err = json_parse_token(json, len, offset, element_data);
				break;

			default:
				return -EINVAL;
			}
			if (err) {
				return err;
			}
		}

		err = json_token_get(json, len, offset, &type, &token, &token_len);
		if (err) {
			return err;
		}

		if (type == JSON_TOKEN_TYPE_END_ARRAY) {
			break;
		}
	}

	arr->elements_count = count + 1;

	return 0;
}

