static int json_obj_encode_field(json_write_obj_func_t writer, void *context,
				 const struct json_obj_descr *descr, const void *data)
{
	int err;

	err = writer(context, "\"%s\":", descr->field_name);
	if (err) {
		return err;
	}

	const void *field_data = (const char *)data + descr->field_offset;

	switch (descr->field_type) {
	case JSON_OBJ_DESCR_FIELD_TYPE_BOOL:
		err = writer(context, "%s", *(bool *)field_data ? "true" : "false");
		break;

	case JSON_OBJ_DESCR_FIELD_TYPE_INT:
		err = writer(context, "%d", *(int32_t *)field_data);
		break;

	case JSON_OBJ_DESCR_FIELD_TYPE_UINT:
		err = writer(context, "%u", *(uint32_t *)field_data);
		break;

	case JSON_OBJ_DESCR_FIELD_TYPE_STRING:
		err = json_write_string(writer, context, field_data);
		break;

	case JSON_OBJ_DESCR_FIELD_TYPE_STRING_ARRAY:
		err = json_write_string_array(writer, context, field_data);
		break;

	case JSON_OBJ_DESCR_FIELD_TYPE_OBJECT:
		err = json_obj_encode(writer, context, descr->object_descr,
				      descr->object_descr_len, field_data);
		break;

	case JSON_OBJ_DESCR_FIELD_TYPE_OBJECT_ARRAY:
		err = json_write_obj_array(writer, context, descr->object_descr,
				       descr->object_descr_len, field_data,
				       descr->field_size);
		break;

	case JSON_OBJ_DESCR_FIELD_TYPE_S64:
		err = writer(context, "%lld", *(int64_t *)field_data);
		break;

	case JSON_OBJ_DESCR_FIELD_TYPE_U64:
		err = writer(context, "%llu", *(uint64_t *)field_data);
		break;

	case JSON_OBJ_DESCR_FIELD_TYPE_FLOAT:
		err = writer(context, "%f", *(double *)field_data);
		break;

	case JSON_OBJ_DESCR_FIELD_TYPE_TOKEN:
		{
			const struct json_token *token = field_data;

			if (token->type == JSON_TOKEN_TYPE_STRING) {
				err = writer(context, "\"%.*s\"", (int)token->len, token->ptr);
			} else {
				err = writer(context, "%.*s", (int)token->len, token->ptr);
			}
		}
		break;

	default:
		return -EINVAL;
	}

	return err;
}

int json_obj_encode(json_write_obj_func_t writer, void *context,
		    const struct json_obj_descr *descr, size_t descr_len,
		    const void *data)
{
	int err;
	bool first_field = true;

	err = writer(context, "{");
	if (err) {
		return err;
	}

	for (size_t i = 0; i < descr_len; i++) {
		const void *field_data = (const char *)data + descr[i].field_offset;

		/* Skip if field is NULL and not a string or token */
		if (field_data == NULL &&
		    descr[i].field_type != JSON_OBJ_DESCR_FIELD_TYPE_STRING &&
		    descr[i].field_type != JSON_OBJ_DESCR_FIELD_TYPE_TOKEN) {
			continue;
		}

		/* Skip if string is NULL */
		if (descr[i].field_type == JSON_OBJ_DESCR_FIELD_TYPE_STRING &&
		    *(const char **)field_data == NULL) {
			continue;
		}

		/* Skip if token is NULL */
		if (descr[i].field_type == JSON_OBJ_DESCR_FIELD_TYPE_TOKEN &&
		    ((const struct json_token *)field_data)->ptr == NULL) {
			continue;
		}

		if (!first_field) {
			err = writer(context, ",");
			if (err) {
				return err;
			}
		}

		err = json_obj_encode_field(writer, context, &descr[i], data);
		if (err) {
			return err;
		}

		first_field = false;
	}

	err = writer(context, "}");
	if (err) {
		return err;
	}

	return 0;
}

int json_write_string(json_write_obj_func_t writer, void *context, const char *str)
{
	int err;

	err = writer(context, "\"");
	if (err) {
		return err;
	}

	for (size_t i = 0; str[i] != '\0'; i++) {
		switch (str[i]) {
		case '"':
			err = writer(context, "\\\"");
			break;

		case '\\':
			err = writer(context, "\\\\");
			break;

		case '\b':
			err = writer(context, "\\b");
			break;

		case '\f':
			err = writer(context, "\\f");
			break;

		case '\n':
			err = writer(context, "\\n");
			break;

		case '\r':
			err = writer(context, "\\r");
			break;

		case '\t':
			err = writer(context, "\\t");
			break;

		default:
			err = writer(context, "%c", str[i]);
			break;
		}

		if (err) {
			return err;
		}
	}

	err = writer(context, "\"");
	if (err) {
		return err;
	}

	return 0;
}

int json_write_string_array(json_write_obj_func_t writer, void *context,
			    const struct json_arr *arr)
{
	int err;

	err = writer(context, "[");
	if (err) {
		return err;
	}

	for (size_t i = 0; i < arr->elements_count; i++) {
		const char *str = ((const char **)arr->elements)[i];

		if (i > 0) {
			err = writer(context, ",");
			if (err) {
				return err;
			}
		}

		err = json_write_string(writer, context, str);
		if (err) {
			return err;
		}
	}

	err = writer(context, "]");
	if (err) {
		return err;
	}

	return 0;
}

int json_write_obj_array(json_write_obj_func_t writer, void *context,
			 const struct json_obj_descr *descr, size_t descr_len,
			 const struct json_arr *arr, size_t element_size)
{
	int err;

	err = writer(context, "[");
	if (err) {
		return err;
	}

	for (size_t i = 0; i < arr->elements_count; i++) {
		const void *element_data = (const char *)arr->elements + (i * element_size);

		if (i > 0) {
			err = writer(context, ",");
			if (err) {
				return err;
			}
		}

		err = json_obj_encode(writer, context, descr, descr_len, element_data);
		if (err) {
			return err;
		}
	}

	err = writer(context, "]");
	if (err) {
		return err;
	}

	return 0;
}
